head.script:
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.vBzProcsNo;
scwin.clickBzProcsNo;
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.pJsMarket = js_market;

// var gAfStdIndCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        if (js_market === "1") {
            panel_KOSDAQ.hide();
            panel_KOSDAQ1.hide();
            panel_KSE.show("");
            panel_APPL_EXCHRT.hide();
            pnl_segment.hide();
        } else if (js_market === "2") {
            panel_KOSDAQ.show("");
            panel_KOSDAQ1.show("");
            panel_KSE.hide();
            panel_APPL_EXCHRT.show("");
            pnl_segment.show("");
        } else {
            scwin.pJsMarket = '1';
        }
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        $c.elw.fn_searchCode();
        await scwin.setComboCode();
        let parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.scwin.clickBzProcsNo;
        scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        // 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
        scwin.btnShow(scwin.vBzProcsNo);
        if (scwin.vBzProcsNo !== "") {
            scwin.readSync();
            txb_SearchCd.setValue(dts_Corp.getCellData(1, "ISUR_CD"));
            txb_SearchNm.setValue(dts_Corp.getCellData(1, "COM_NM"));
            cmb_SECUGRP_ID.setDisabled(true);
        } else {
            cmb_SECUGRP_ID.setValue(parentWin.cmb_NEW_SECUGRP_ID.getValue()); // 부모창에서 증권그룹값이 가져온다.
            cmb_SPOT_ISU_TRD_MKT_TP_CD.setValue(scwin.pJsMarket);
            buttonSet.setInsertStatus();
        }
        $c.lic.fn_gridNameChange2(cmb_SECUGRP_ID.getValue());
        if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "1") {
            label_58.show("");
            label_32.hide();
            edt_ACNTCLS_MM1.Format = "MM월 DD일";
        } else if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "2") {
            label_58.hide();
            label_32.show("");
            edt_ACNTCLS_MM1.Format = "MM월";
        } else {
            label_58.show("");
            label_32.hide();
            edt_ACNTCLS_MM1.Format = "MM월 DD일";
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05007.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_CoSearch_onclick
 * @description img_CoSearch 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_CoSearch_onclick = async function() {
    try {
        if (cmb_SECUGRP_ID.getValue() === "") {
            await $c.win.alert("[유가증권]을 선택하세요.");
            return;
        }
        scwin.getPar = scwin.getParIsur;
        scwin.setPar = scwin.setParIsur;
        $c.lc.fn_PopFindExamCorp(cmb_SECUGRP_ID.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05007.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name btn_IsuNew_onclick
 * @description 「상장종목신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_IsuNew_onclick = function() {
    try {
        // alert("getObjectValue(cmb_SECUGRP_ID)="+getObjectValue(cmb_SECUGRP_ID));
        if ((js_market === "1") &&
            (cmb_SECUGRP_ID.getValue() === "ST" || cmb_SECUGRP_ID.getValue() === "DR" || cmb_SECUGRP_ID.getValue() === "FS")) {
            $c.pre_newlisting.fn_OpenDetailCorpIsu_protect(-9999);
        } else {
            $c.pre_newlisting.fn_OpenDetailCorpIsu(-9999);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05007.btn_IsuNew_onclick" });
    }
};

/**
 * @method
 * @name grd_IssList_OnDblClick
 * @description grd_IssList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssList_OnDblClick = function(row, colid) {
    try {
        // alert('[dts_Isu]'+dts_Isu.Status);

        // alert("getObjectValue(cmb_SECUGRP_ID)="+getObjectValue(cmb_SECUGRP_ID));
        if ((js_market === "1") &&
            (cmb_SECUGRP_ID.getValue() === "ST" || cmb_SECUGRP_ID.getValue() === "DR" || cmb_SECUGRP_ID.getValue() === "FS")) {
            $c.pre_newlisting.fn_OpenDetailCorpIsu_protect(row);
        } else {
            $c.pre_newlisting.fn_OpenDetailCorpIsu(row);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05007.grd_IssList_OnDblClick" });
    }
};

/**
 * @method
 * @name img_ISUR_SYMBL_onclick
 * @description 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISUR_SYMBL_onclick = async function() {
    try {
        if (txb_ISUR_SYMBL.getValue() === "") {
            await $c.win.alert("[영문회사심볼]을 입력하세요.");
            txb_ISUR_SYMBL.focus();
            return false;
        } else {
            if ($c.lc.fn_eng_symbl_check(txb_ISUR_SYMBL.getValue())) {
                $c.lc.fn_chkCorpSymblDoubleInput(txb_ISUR_SYMBL.getValue(), txb_ISUR_CD.getValue(), dts_Symbl);
                if (!$c.ut.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
                    await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                }
            } else {
                txb_ISUR_SYMBL.focus();
                return false;
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05007.img_ISUR_SYMBL_onclick" });
    }
};

