/**
 * @method
 * @name dts_Corp_OnLoadCompleted
 * @description dts_Corp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Corp_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            if (edt_LIST_DD.getValue() > scwin.vCurDate) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus(); // disable 시킨다.

            }
        }
        if (txb_LIST_NO.getValue() !== "") {
            img_LIST_NO.setBackgroundImage("../img/btn_LstNoCrt_d.gif");
            img_LIST_NO.setDisabled(true);
        }

        // gAfStdIndCd = dts_Corp.NameValue(1, "AF_STD_IND_CD");
        /*
        if (getObjectValue(txb_FSS_UNQ_NO) == "") {
        	alert(getMessageParam("MSG-0025", ""));
        	buttonSet.setErrorStatus(); //disable 시킨다.
        }
         */
        if (dts_Corp.getCellData(1, "SPOT_ISU_TRD_MKT_TP_CD") === "2") {
            pnl_segment.show("");
        } else {
            pnl_segment.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05007.dts_Corp_OnLoadCompleted" });
    }
};

/**
 * @method
