 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05007.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh();

        // 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
        scwin.btnShow(scwin.vBzProcsNo);
        if (buttonSet.status === "U") {
            let parentWin = $c.frame.path("../");
            parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
        }
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            if (js_market === "2") {
                // 저장시 소속부변경 알림 팝업
                await $c.win.alert("소속부변경_STF05234 화면에서 확인하여 주십시오");
            }
            await $c.win.closePopup();
        } else {
            scwin.readSync();
            if (js_market === "2") {
                // 저장시 소속부변경 알림 팝업
                await $c.win.alert("소속부변경_STF05234 화면에서 확인하여 주십시오");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05007.trs_Save_OnSuccess" });
    }
};

