            id: "ULDSTF05814",
            title: "세그먼트 관리",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("./ULDSTF05814.gfm", options);
