/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_SearchCd.setValue(arrPar[0].ISUR_CD);
        txb_SearchNm.setValue(arrPar[0].COM_NM);
        const exemBzProcsNo = arrPar[0].BZ_PROCS_NO;
        // alert("[예비심사의 업무처리번호]"+exemBzProcsNo);
        // 업무처리번호대신 mktTpCd 값으로도 구분해서 사용할수 있음
        if (exemBzProcsNo === "") {
            $c.pre_newlisting.fn_getCorpInfo_read_sync(dts_Corp, txb_SearchCd.getValue());
        } else {
            // alert("[예비심사의 업무처리번호]"+exemBzProcsNo);
            $c.pre_newlisting.fn_getExem_read_sync(dts_Corp, exemBzProcsNo);
        }
        // 데이타셋에 다시한번 settion한다.
        let parentWin = $c.frame.path("../");
        cmb_SPOT_ISU_TRD_MKT_TP_CD.setValue(scwin.pJsMarket);
    }
};

