/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        return false;
    }
    if (cmb_SECUGRP_ID.getValue() === "") {
        await $c.win.alert("[유가증권]을 선택하세요.");
        return false;
    }
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (scwin.TR_JOB === 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, txb_ISUR_CD.getValue())) return false;
    }
    if (txb_FSS_UNQ_NO.getValue() === "") {
        await $c.win.alert("[금감원고유번호]을 입력하세요.");
        txb_FSS_UNQ_NO.focus();
        return false;
    }
    if (txb_COM_NM.getValue() === "") {
        await $c.win.alert("[한글회사명]을 입력하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if (txb_COM_ABBRV.getValue() === "") {
        await $c.win.alert("[한글회사약명]을 입력하세요.");
        txb_COM_ABBRV.focus();
        return false;
    }
    if (txb_COM_ENG_NM.getValue() === "") {
        await $c.win.alert("[영문회사명]을 입력하세요.");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (txb_COM_ENG_ABBRV.getValue() === "") {
        await $c.win.alert("[영문회사약명]을 입력하세요.");
        txb_COM_ENG_ABBRV.focus();
        return false;
    }
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "1") {
        if (txb_ISUR_SYMBL.getValue() === "") {
            await $c.win.alert("[영문회사심볼]을 입력하세요.");
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if ($c.lc.fn_eng_symbl_check(txb_ISUR_SYMBL.getValue())) {
            if (!$c.lc.fn_chkCorpSymblDoubleInput(txb_ISUR_SYMBL.getValue(), txb_ISUR_CD.getValue(), dts_Symbl)) {
                await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                return false;
            }
        } else {
            txb_ISUR_SYMBL.focus();
            return false;
        }
    }
    if (txb_CEO_NM.getValue() === "") {
        await $c.win.alert("[대표이사명]을 입력하세요.");
        txb_CEO_NM.focus();
        return false;
    }
    /*
    if (getObjectValue(edt_BZ_REG_NO) == "") {
    	alert("[사업자등록번호]을 입력하세요.");edt_BZ_REG_NO.focus();return false;
    }
    if (getObjectValue(edt_CORP_REG_NO) == "") {
    	alert("[회사등록번호]을 입력하세요.");edt_CORP_REG_NO.focus();return false;
    }
     */

    if (edt_FOUND_DD.getValue() === "") {
        await $c.win.alert("[설립일]을 입력하세요.");
        edt_FOUND_DD.focus();
        return false;
    }
    if (txb_LIST_NO.getValue() === "") {
        await $c.win.alert("[상장번호]을 입력하세요.");
        txb_LIST_NO.focus();
        return false;
    }
    if (edt_STKCERT_LIST_APPROV_DD.getValue() === "") {
        await $c.win.alert("[상장승인일]을 입력하세요.");
        edt_STKCERT_LIST_APPROV_DD.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (scwin.vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (txb_STD_IND_CD.getValue() === "") {
        await $c.win.alert("[업종]을 선택하세요.");
        txb_STD_IND_CD.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_ZIPCD) == "" || getObjectValue(txb_ZIPCD).length != 6) {
    	alert("[우편번호]을 선택하세요.");txb_ZIPCD.focus();return false;
    }
     */
    if (txb_ADDR.getValue() === "") {
        await $c.win.alert("[주소]를 입력하세요.");
        txb_ZIPCD.focus();
        return false;
    }
    if (cmb_LIST_CLSS_CD.getValue() === "") {
        await $c.win.alert("[상장구분]을 선택하세요.");
        cmb_LIST_CLSS_CD.focus();
        return false;
    }
    if (cmb_TRANSSTK_AGNT_CD.getValue() === "") {
        await $c.win.alert("[명의개서대행기관]을 선택하세요.");
        cmb_TRANSSTK_AGNT_CD.focus();
        return false;
    }
    if (cmb_EXT_AUDTR_CD.getValue() === "") {
        await $c.win.alert("[외부감사인]을 선택하세요.");
        cmb_EXT_AUDTR_CD.focus();
        return false;
    }
    if (txb_CORP_TEL_NO.getValue() === "") {
        await $c.win.alert("[회사전화번호]을 입력하세요.");
        txb_CORP_TEL_NO.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_HPAGE) == "") {
    	alert("[홈페이지]를 입력하세요.");txb_HPAGE.focus();return false;
    }
     */

    if (txb_MAJ_PROD_NM.getValue() === "") {
        await $c.win.alert("[주요제품]을 입력하세요.");
        txb_MAJ_PROD_NM.focus();
        return false;
    }
    if (edt_ACNTCLS_MM1.getValue() === "") {
        await $c.win.alert("[결산월]을 입력하세요.");
        edt_ACNTCLS_MM1.focus();
        return false;
    }
    if (!$c.pre_newlisting.fn_checkAcntclsMM(edt_ACNTCLS_MM1)) return false;
    if (cmb_MAINTR_BK_CD.getValue() === "") {
        await $c.win.alert("[주거래은행]을 선택하세요.");
        cmb_MAINTR_BK_CD.focus();
        return false;
    }

    // 재상장-인적분할 회사라 회사에서 직접 상장 2009.03.19
    if (cmb_LIST_CLSS_CD.getValue() === '10') {
        // 신규상장
        if (txb_LEADCOM_MBR_NM_STR.getValue() === "") {
            await $c.win.alert("[상장주선인]을 선택하세요.");
            txb_LEADCOM_MBR_NM_STR.focus();
            return false;
        }
    }

    // 부실기재건수 2011.02.11 실뢰평가점수에서 부실기재건수로 변경됨.
    // 부실기재건수 2011.02.11 실뢰평가점수에서 부실기재건수로 변경됨.
    if (cmd_ConfPnt.getText() === "") {
        await $c.win.alert("[부실기재건수]을 선택하세요.");
        cmd_ConfPnt.focus();
        return false;
    }
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "2") {
        if (cmb_SECT_TP_CD.getValue() === "") {
            await $c.win.alert("[소속부]를 선택하세요.");
            cmb_SECT_TP_CD.focus();
            return false;
        }
    }
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "2" && cmb_SEG_TP_CD.getValue() === "") {
        await $c.win.alert("[세그먼트]를 선택하세요.");
        cmb_SEG_TP_CD.focus();
        return false;
    }
    if (cmb_DIRCTLIST_CORP_YN.getValue() === "") {
        await $c.win.alert("[직상장법인여부]를 선택하세요.");
        cmb_DIRCTLIST_CORP_YN.focus();
        return false;
    }
    if (cmb_COND_LIST_YN.getValue() === "") {
        await $c.win.alert("[조건부상장여부]를 선택하세요.");
        cmb_COND_LIST_YN.focus();
        return false;
    }
    if (cmb_VENTBZ_YN.getValue() === "") {
        await $c.win.alert("[벤처기업여부]를 선택하세요.");
        cmb_VENTBZ_YN.focus();
        return false;
    }
    if (cmb_SME_YN.getValue() === "") {
        await $c.win.alert("[중소기업여부]를 선택하세요.");
        cmb_SME_YN.focus();
        return false;
    }
    if (cmb_PRELM_INVSTG_COM_TP_CD.getValue() === "") {
        if (js_market === "2" || js_market === "6") {
            await $c.win.alert("[기업구분]를 선택하세요.");
            cmb_PRELM_INVSTG_COM_TP_CD.focus();
            return false;
        }
    }

    /*
    if (getObjectValue(cmb_CAP_INROAD_YN) == "") {
    	alert("[자본잠식여부]를 선택하세요.");cmb_CAP_INROAD_YN.focus();return false;
    }
     */
    if (cmb_PEPLSTK_YN.getValue() === "") {
        await $c.win.alert("[국민주여부]를 선택하세요.");
        cmb_PEPLSTK_YN.focus();
        return false;
    }
    if (cmb_CURR_ISO_CD.getValue() === "") {
        await $c.win.alert("[통화표시]를 선택하세요.");
        cmb_CURR_ISO_CD.focus();
        return false;
    }
    if (js_market === "2") {
        if (edt_APPL_EXCHRT.getValue() === "") {
            await $c.win.alert("[적용환율]을 입력하세요.");
            edt_APPL_EXCHRT.focus();
            return false;
        }
    }
    if (txa_MAJSHRHD_CONTN.getValue() === "") {
        await $c.win.alert("[주요주주관련]을 입력하세요.");
        txa_MAJSHRHD_CONTN.focus();
        return false;
    }
    if (cmb_SECUGRP_ID.getValue() === SECUGRP_ID_DR) {
        if (edt_PER1DR_FORNSTK_RTO.getValue() === "") {
            await $c.win.alert("[1DR당원주비율]을 입력하세요.");
            edt_PER1DR_FORNSTK_RTO.focus();
            return false;
        }
        if (txb_FORNSTK_STORG_INST_NM.getValue() === "") {
            await $c.win.alert("[원주보관기관]을 입력하세요.");
            txb_FORNSTK_STORG_INST_NM.focus();
            return false;
        }
        if (txb_LIST_FORN_EXCH_NM1.getValue() === "") {
            await $c.win.alert("[상장해외거래소1]을 입력하세요.");
            txb_LIST_FORN_EXCH_NM1.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);

        // alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Corp.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TR_JOB_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        // alert("dts_Corp :"+dts_Corp.Text);
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name checkBiz
 * @description check Biz 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBiz = async function() {
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[상장종목]을 입력하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (!await scwin.checkBiz()) {
        return;
    }

    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
     */
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        const Mkt_Id = dts_Corp.getCellData(dts_Corp.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD");
        const gSecugrpID = cmb_SECUGRP_ID.getValue();
        if (Mkt_Id === "1") {
            if (gSecugrpID === SECUGRP_ID_FS) {
                arr[0] = "68152B";
            } else if (gSecugrpID === SECUGRP_ID_DR) {
                arr[0] = "68152C";
            }
            arr[5] = $c.pre_newlisting.fn_getDsclsTitle(txb_COM_NM.getValue(), edt_LIST_DD.getValue());

            // 신규상장공시문생성조회(pre_newlisting)
            $c.pre_newlisting.fn_read_sync_corpisu_discls(dts_Discls_Isu, txb_ISUR_CD.getValue(), edt_LIST_DD.getValue());
            $c.stf.copyDataSet(dts_Discls_Isu, param_dts_isu);
        } else if (Mkt_Id === "2") {
            arr[0] = "70760";
            $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        }
        let dBzProcsNo = scwin.vBzProcsNo;
        for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo === "" ? "" : ",") + dts_Isu.getCellData(i, "BZ_PROCS_NO");
        }
        arr[1] = dBzProcsNo;
        // arr[1] = dts_Corp.NameValue(1, "BZ_PROCS_NO") ;
        arr[2] = dts_Corp.getCellData(1, "ISUR_CD");
        arr[3] = Mkt_Id;
        $c.stf.copyDataSet(dts_Corp, param_dts_mst);
        for (i = 1; i <= param_dts_isu.getRowCount(); i++) {
            if (param_dts_isu.getCellData(i, "STKCERT_KIND_CD") === "000") {
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DIV_RECK_DD1", param_dts_isu.getCellData(i, "DIV_RECK_DD1"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_PRC", param_dts_isu.getCellData(i, "ISU_PRC"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CD", param_dts_isu.getCellData(i, "ISU_CD"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_SRT_CD", param_dts_isu.getCellData(i, "ISU_SRT_CD"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_DD", param_dts_isu.getCellData(i, "ISU_DD"));
            }
        }
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    let wth = 730 + 5;
    let hgt = 785 + 30;
    let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

