/**
 * @method
 * @name btnShow
 * @description 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.btnShow = function(val) {
    if (val !== "") {
        // 업무처리번호가 있음.
        btn_IsuNew.setBackgroundImage("../img/btn_IsuNew.gif");
        btn_IsuNew.setDisabled(false);
        lab_btn.hide();
    } else {
        btn_IsuNew.setBackgroundImage("../img/btn_IsuNew_d.gif");
        btn_IsuNew.setDisabled(true);
        lab_btn.show("");
    }
};
